"""Build the unpublished 2SW Week 5 communication module, practice quiz, and discussion."""

import asyncio, json, mimetypes, re, sys
from pathlib import Path
import httpx

BASE="https://learn.irvingisd.net"; COURSE_ID=98060
MODULE_NAME="2SW Wk5: Communication and Goal Setting"
QUIZ_TITLE="PRACTICE: Active Listening Evidence Check"
DISCUSSION_TITLE="PRACTICE: Little Library Message Lab"
ROOT=Path(__file__).resolve().parents[2]; TEMPLATES=Path(__file__).parent/"templates"
ASSETS=ROOT/"cce-curriculum/resources/canvas-licensed/2sw/wk5"

def slugify(v): return re.sub(r"[^a-z0-9]+","-",v.lower().replace("&","and")).strip("-")
async def api(c,m,p,**kw):
    r=await c.request(m,f"{BASE}/api/v1{p}",**kw); r.raise_for_status(); return r.json() if r.content else None
async def paged(c,p,params=None):
    out=[]; url=f"{BASE}/api/v1{p}"; q={"per_page":100,**(params or {})}
    while url:
        r=await c.get(url,params=q); r.raise_for_status(); out+=r.json(); url=r.links.get("next",{}).get("url"); q=None
    return out
async def ensure_module(c):
    modules=await paged(c,f"/courses/{COURSE_ID}/modules"); found=next((m for m in modules if m["name"]==MODULE_NAME),None)
    return found or await api(c,"POST",f"/courses/{COURSE_ID}/modules",data={"module[name]":MODULE_NAME,"module[published]":"false"})
async def ensure_folder(c,path):
    current=""; folder=None
    for name in path.split("/")[1:]:
        target=f"{current}/{name}".strip("/"); enc=httpx.URL("/"+target).raw_path.decode("ascii").lstrip("/")
        r=await c.get(f"{BASE}/api/v1/courses/{COURSE_ID}/folders/by_path/{enc}")
        if r.status_code==200 and r.json(): folder=r.json()[-1]
        else: folder=await api(c,"POST",f"/courses/{COURSE_ID}/folders",data={"name":name,"parent_folder_path":"course files"+(f"/{current}" if current else ""),"locked":"true"})
        current=target
    if folder and not folder.get("locked"): folder=await api(c,"PUT",f"/folders/{folder['id']}",data={"locked":"true"})
    return folder
async def upload(c,path,folder):
    init=await api(c,"POST",f"/courses/{COURSE_ID}/files",data={"name":path.name,"parent_folder_path":folder,"on_duplicate":"overwrite"})
    r=await c.post(init["upload_url"],data=init["upload_params"],files={"file":(path.name,path.read_bytes(),mimetypes.guess_type(path.name)[0] or "application/octet-stream")},follow_redirects=True); r.raise_for_status(); return r.json()
def render(name,values):
    text=(TEMPLATES/name).read_text()
    for k,v in values.items(): text=text.replace("{{"+k+"}}",str(v))
    unresolved=sorted(set(re.findall(r"\{\{[^}]+\}\}",text)))
    if unresolved: raise ValueError(f"Unresolved values in {name}: {unresolved}")
    return text
async def upsert_page(c,title,body,url):
    data={"wiki_page[title]":title,"wiki_page[body]":body,"wiki_page[published]":"false","wiki_page[editing_roles]":"teachers"}; r=await c.get(f"{BASE}/api/v1/courses/{COURSE_ID}/pages/{url}")
    if r.status_code==200: return await api(c,"PUT",f"/courses/{COURSE_ID}/pages/{url}",data=data)
    if r.status_code!=404: r.raise_for_status()
    return await api(c,"POST",f"/courses/{COURSE_ID}/pages",data=data)
async def upsert_page_item(c,module_id,page,title):
    items=await paged(c,f"/courses/{COURSE_ID}/modules/{module_id}/items"); item=next((i for i in items if i.get("page_url")==page["url"]),None)
    if item: return await api(c,"PUT",f"/courses/{COURSE_ID}/modules/{module_id}/items/{item['id']}",data={"module_item[title]":title})
    return await api(c,"POST",f"/courses/{COURSE_ID}/modules/{module_id}/items",data={"module_item[type]":"Page","module_item[page_url]":page["url"],"module_item[title]":title})
def file_link(file_id,label): return f'<a href="/courses/{COURSE_ID}/files/{file_id}/preview" data-api-endpoint="/api/v1/courses/{COURSE_ID}/files/{file_id}" data-api-returntype="File">{label}</a>'
def image_tag(file_id,alt,max_width=760): return f'<img src="/courses/{COURSE_ID}/files/{file_id}/preview" alt="{alt}" style="display:block;width:100%;max-width:{max_width}px;height:auto;margin:14px auto;border:1px solid #ddd" data-api-endpoint="/api/v1/courses/{COURSE_ID}/files/{file_id}" data-api-returntype="File">'
def step(num,title,body,color="#5a2d91"): return f'<h3 style="color:{color};border-bottom:3px solid #d9c9ed">{num}. {title}</h3>{body}'
def flow(color,title,text): return f'<div style="border-left:5px solid {color};padding-left:16px;margin:18px 0"><h4 style="margin:0;color:{color}">{title}</h4><p>{text}</p></div>'

QUIZ_QUESTIONS=[
 {"name":"Q1 - Essential detail","text":"Which detail from Maria's fictional account is essential to record?","correct":"The chest tightness started about three hours ago and has not gone away.","wrong":["She had paperwork after lunch.","She usually carries coffee.","She had a busy week."],"correct_comment":"Correct. Onset and persistence are key reported details.","incorrect_comment":"Choose a detail that directly describes the reported concern, timing, or risk context."},
 {"name":"Q2 - New question","text":"Which question asks for information Maria did not already give?","correct":"Have you noticed nausea, sweating, or dizziness?","wrong":["Did the pain start today?","Has the pain gone away?","Did it spread into your shoulder?"],"correct_comment":"Correct. The account did not answer that question.","incorrect_comment":"A clarifying question closes a gap instead of repeating a known detail."},
 {"name":"Q3 - Role boundary","text":"A classmate reports real chest pain and shortness of breath. What should you do?","correct":"Get an adult and emergency help immediately.","wrong":["Practice the classroom questions first.","Decide whether it is serious.","Wait until the end of class."],"correct_comment":"Correct. Real symptoms are not a classroom practice case.","incorrect_comment":"Do not diagnose or delay. Get immediate adult or emergency help."},
 {"name":"Q4 - Paraphrase","text":"Which response best shows active listening in the equipment scenario?","correct":"I heard that the cart wheel sticks only when the cart is full. What load was on it when that happened?","wrong":["The cart is definitely broken.","Just submit the request again.","That happened to me once."],"correct_comment":"Correct. It paraphrases and asks a new question.","incorrect_comment":"Look for both a faithful paraphrase and a question that closes a gap."},
 {"name":"Q5 - Transfer","text":"Which example shows active listening transferring to another career?","correct":"A mechanic repeats the driver's concern and asks when the sound occurs.","wrong":["A designer chooses a favorite color.","A chef memorizes a recipe alone.","A student guesses what a customer meant."],"correct_comment":"Correct. The listener paraphrases and asks for useful detail.","incorrect_comment":"Transfer evidence names the career and the same listening action."}
]
async def upsert_quiz(c):
    quizzes=await paged(c,f"/courses/{COURSE_ID}/quizzes"); quiz=next((q for q in quizzes if q.get("title")==QUIZ_TITLE),None)
    data={"quiz[title]":QUIZ_TITLE,"quiz[description]":"<p>Ungraded active-listening practice. Retry and use the feedback.</p>","quiz[quiz_type]":"practice_quiz","quiz[published]":"false","quiz[allowed_attempts]":"-1","quiz[show_correct_answers]":"true","quiz[shuffle_answers]":"false"}
    quiz=await api(c,"PUT" if quiz else "POST",f"/courses/{COURSE_ID}/quizzes/{quiz['id']}" if quiz else f"/courses/{COURSE_ID}/quizzes",data=data)
    existing=await paged(c,f"/courses/{COURSE_ID}/quizzes/{quiz['id']}/questions")
    for position,spec in enumerate(QUIZ_QUESTIONS,start=1):
        found=next((q for q in existing if q.get("question_name")==spec["name"]),None); answers=[{"answer_text":spec["correct"],"answer_weight":100}]+[{"answer_text":v,"answer_weight":0} for v in spec["wrong"]]
        payload={"question":{"question_name":spec["name"],"question_text":spec["text"],"question_type":"multiple_choice_question","position":position,"points_possible":1,"correct_comments":spec["correct_comment"],"incorrect_comments":spec["incorrect_comment"],"answers":answers}}
        await api(c,"PUT" if found else "POST",f"/courses/{COURSE_ID}/quizzes/{quiz['id']}/questions/{found['id']}" if found else f"/courses/{COURSE_ID}/quizzes/{quiz['id']}/questions",json=payload)
    return await api(c,"GET",f"/courses/{COURSE_ID}/quizzes/{quiz['id']}")
async def upsert_quiz_item(c,module_id,quiz):
    items=await paged(c,f"/courses/{COURSE_ID}/modules/{module_id}/items"); item=next((i for i in items if i.get("type")=="Quiz" and i.get("content_id")==quiz["id"]),None)
    if item: return await api(c,"PUT",f"/courses/{COURSE_ID}/modules/{module_id}/items/{item['id']}",data={"module_item[title]":QUIZ_TITLE})
    return await api(c,"POST",f"/courses/{COURSE_ID}/modules/{module_id}/items",data={"module_item[type]":"Quiz","module_item[content_id]":quiz["id"],"module_item[title]":QUIZ_TITLE})
async def upsert_discussion(c):
    topics=await paged(c,f"/courses/{COURSE_ID}/discussion_topics"); found=next((d for d in topics if d.get("title")==DISCUSSION_TITLE),None)
    message='<p><strong>This is a fictional message lab.</strong> Do not use a real account, address, photo, handle, phone number, or personal name.</p><ol><li>Post a 2-4 sentence Little Library update with a clear status, one reader action, and two useful hashtags.</li><li>Reply to one classmate with Notice + Question + Next Step.</li></ol><p>A private written response to the same prompts is an equal route.</p>'
    data={"title":DISCUSSION_TITLE,"message":message,"discussion_type":"threaded","published":"false","require_initial_post":"true"}
    if found: return await api(c,"PUT",f"/courses/{COURSE_ID}/discussion_topics/{found['id']}",data=data)
    return await api(c,"POST",f"/courses/{COURSE_ID}/discussion_topics",data=data)
async def upsert_discussion_item(c,module_id,discussion):
    items=await paged(c,f"/courses/{COURSE_ID}/modules/{module_id}/items"); item=next((i for i in items if i.get("type")=="Discussion" and i.get("content_id")==discussion["id"]),None)
    if item: return await api(c,"PUT",f"/courses/{COURSE_ID}/modules/{module_id}/items/{item['id']}",data={"module_item[title]":DISCUSSION_TITLE})
    return await api(c,"POST",f"/courses/{COURSE_ID}/modules/{module_id}/items",data={"module_item[type]":"Discussion","module_item[content_id]":discussion["id"],"module_item[title]":DISCUSSION_TITLE})

async def main():
    token=sys.stdin.readline().strip()
    if not token: raise SystemExit("Canvas token required on stdin")
    async with httpx.AsyncClient(headers={"Authorization":f"Bearer {token}"},timeout=120) as c:
        module=await ensure_module(c); quiz=await upsert_quiz(c); discussion=await upsert_discussion(c)
        names={"GUIDE":"2sw-wk5-powerskills-transfer-guide.pdf","CONFLICT":"2sw-wk5-conflict-resolution-plan.pdf","LISTEN":"2sw-wk5-active-listening-lab.pdf","SMART":"2sw-wk5-advocacy-smart-time-plan.pdf","WRITE":"2sw-wk5-written-message-lab.pdf","SYNTH":"2sw-wk5-work-experience-skills-synthesis.pdf","RUBRIC":"2sw-wk5-communication-goal-rubric.pdf"}
